<script lang="ts">import {onMount} from 'svelte';import AppHeader from '$lib/AppHeader.svelte';import {Vote,Sparkles,ArrowUpRight,RefreshCw} from 'lucide-svelte';type Poll={id:string;title:string;created:number;closed:number|null;votes:number};let polls=$state<Poll[]>([]),loading=$state(true),message=$state('');async function load(){loading=true;message='';try{const r=await fetch('/api/polls',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.message);polls=d.polls;}catch(e){message=e instanceof Error?e.message:'Your polls could not load.';}finally{loading=false;}}onMount(()=>{load();let timer=setInterval(()=>{if(!document.hidden)load();},10000);return()=>clearInterval(timer);});</script>
<svelte:head><title>My Nail Polls — Rose Atelier</title></svelte:head>
<div class="app-shell"><AppHeader/><main class="polls-main"><div class="gallery-heading"><div><span class="eyebrow">A LITTLE GROUP DECISION</span><h1>Your looks.<br/><i>Their favorites.</i></h1><p>Share four designs from today and let your friends choose. Open a poll to see live results or close voting.</p></div><a class="primary" href="/gallery"><Sparkles size={17}/>Create a poll from my gallery</a></div>{#if message}<div class="gallery-empty" role="alert"><p>{message}</p><button class="primary" onclick={load}><RefreshCw size={16}/>Try again</button></div>{:else if !polls.length}<div class="gallery-empty"><span class="empty-flower"><Vote size={32}/></span><h2>{loading?'Opening your polls…':'Make your next manicure a group decision.'}</h2><p>Choose four looks made today in your gallery to publish your first poll.</p><a class="primary" href="/gallery">Choose my four looks</a></div>{:else}<div class="poll-list">{#each polls as poll}<a href={`/p/${poll.id}`}><div class="poll-list-icon"><Vote size={25}/></div><div><span class="eyebrow">{poll.closed?'CLOSED':'LIVE'} · {poll.votes} VOTES</span><h2>{poll.title}</h2><p>{new Date(poll.created).toLocaleDateString()}</p></div><ArrowUpRight size={22}/></a>{/each}</div>{/if}</main></div>
